import { expect, it } from 'vitest';
import { toCsv } from './csv';

it('writes dates in UTC', () => {
  process.env.TZ = 'America/New_York';
  expect(toCsv([{ id: 1, at: '2026-01-02T03:04:05Z', total: 9 }])).toBe('1,2026-01-02T03:04:05.000Z,9');
});

